import hashlib,json,numpy as np
from pathlib import Path
from sensor_msgs.msg import PointCloud2
p=Path('/home/l/remani_ws/experiments/online_remani_validation/results/nav_map_probe_20261112-1640')
h=json.loads((p/'mapping_history.json').read_text()); a=json.loads((p/'continuous_cloud_static_voxel_audit.json').read_text()); centers=np.asarray([x['center'] for x in a['occupied_cells']]); out=[{'goal':x['goal'],'center':x['center'],'frame_count':0,'free_ray_box_crossings':0,'crossings':[]} for x in a['occupied_cells']]; perframe=[]
