for e in h:
 m=PointCloud2().deserialize((p/e['file']).read_bytes()); offs={f.name:f.offset for f in m.fields}; dt=np.dtype({'names':['x','y','z'],'formats':['<f4']*3,'offsets':[offs[k] for k in ['x','y','z']],'itemsize':m.point_step}); xyz=np.ndarray((m.height,m.width),dtype=dt,buffer=m.data,strides=(m.row_step,m.point_step)); pts=np.column_stack([xyz[k].ravel() for k in ['x','y','z']]);x,y,z,w=e['rotation'];R=np.array([[1-2*(y*y+z*z),2*(x*y-z*w),2*(x*z+y*w)],[2*(x*y+z*w),1-2*(x*x+z*z),2*(y*z-x*w)],[2*(x*z-y*w),2*(y*z+x*w),1-2*(x*x+y*y)]]);o=np.asarray(e['translation']); world=pts@R.T+o; ok=np.isfinite(world).all(1)&(np.abs(pts)<[8,8,3]).all(1)&(world[:,2]>=.15); ids=np.flatnonzero(ok); world=world[ok]; original=world.copy(); d=world-o; original_length=np.linalg.norm(d,axis=1); inmap=((world>=bmin+1e-4)&(world<=bmax-1e-4)).all(1)
 # Native closetPointInMap: first positive boundary intersection minus .001 in ray parameter.
 for n in np.flatnonzero(~inmap):
  dn=d[n]; params=[]
